/* =====================================================================
   ORDER PDF ASSETS — fonts and logo for the customer order PDF
   ---------------------------------------------------------------------
   Loaded on demand by js/order-pdf.js (only on the checkout page, only
   when a PDF is made). Kept as a .js file so it also works when the site
   is opened straight from the folder (file://), where fetch() is blocked.

   • Noto Sans Regular + Bold (subset: Latin, ₹ and punctuation)
   • Playfair Display Bold (subset: shop name / title)
     Both fonts: SIL Open Font License 1.1 — see assets/fonts/OFL.txt
   • Varam Crackers logo (JPEG on white) from assets/logo/varam-logo.webp

   This file is generated — don't edit it by hand.
   ===================================================================== */
window.VC_PDF_ASSETS = {
  version: 1,
  fonts: {
    "NotoSans-Regular.ttf": "",
    "NotoSans-Bold.ttf": "",
    "PlayfairDisplay-Bold.ttf": ""
  },
  /* Unicode code points the body font can draw. Customer text with other
     characters (e.g. Tamil) is drawn as a picture instead, so it still
     shows correctly in the PDF. */
  coverage: [[32, 126], [160, 591], [710, 733], [8192, 8292], [8294, 8303], [8377, 8377], [8470, 8470], [8482, 8482], [8722, 8722], [65533, 65533]],
  logo: { data: "data:image/jpeg;base64,", width: 201, height: 300 }
};
